<script module lang="ts">
/**
 * A Button preset for signing in with an identity provider (`design/components/provider-button.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/provider-button.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  BrandMark,
  Icon,
  agentMember,
  agentPress,
  chainHandlers,
  joinSlot,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/provider-button.module.css'

export type ProviderButtonProvider = ProviderButtonProps['provider']

export interface ProviderButtonProps {
  /**
   * Links supporting text, such as "Your organization requires single sign-on", to the button.
   */
  'aria-describedby'?: string
  disabled?: boolean
  /**
   * The full label in the app's language, such as "Continue with Google". It is required and
   * passed whole, because the vocabulary has no built-in text, word order around a brand name
   * differs by language, and the provider's terms govern the wording.
   */
  label: string
  /**
   * The sign-in flow has started and not finished. Keeps focus, colours and name, and ignores
   * presses.
   */
  loading?: boolean
  onClick?: (event: MouseEvent) => void
  /**
   * Which mark is drawn, from `BrandMark`'s fixed set.
   */
  provider: 'google' | 'microsoft' | 'github'
  size?: 'sm' | 'md' | 'lg'
  type?: 'button' | 'submit'
}
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  disabled = false,
  label: labelOwn,
  loading = false,
  onClick: onClickOwn,
  provider,
  size = 'md',
  type = 'button',
}: ProviderButtonProps = $props()
const joined = joinSlot(undefined, () => ({ disabled: disabled, label: labelOwn, size: size }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const onClick = $derived(chainHandlers(onClickOwn, joined.passed['onClick']))
let control = $state<HTMLElement | null>(null)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'ProviderButton',
    element: () => control,
    state: () => ({ disabled: disabled, loading: loading }),
    actions: { press: () => agentPress(control) },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<button
    bind:this={control}
    class={styles.button}
    {type}
    {disabled}
    aria-busy={loading ? true : undefined}
    aria-describedby={ariaDescribedby}
    data-variant="outline"
    data-tone="neutral"
    data-size={size}
    data-state={loading ? 'loading' : undefined}
    data-disabled={(disabled) ? '' : undefined}
    data-provider={provider}
    data-member="provider-button"
    onclick={(event) => { if (!loading) onClick?.(event) }}
    >{#if loading
      }<span class={styles.spinner}><Icon name="loading" {size} /></span
    >{:else
      }<span class={styles.mark}><BrandMark name={provider} {size} /></span
    >{/if
    }<span class={styles.label}>{label}</span
  ></button
>{/if
}{@render joined.end?.()}
